#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: the one-time first publish of a new package (docs/PUBLISHING.md).
# npm only lets a package that exists take a trusted publisher, so each new
# package gets a 0.0.0 placeholder published by hand, then a trusted publisher
# for release.yml. The Release workflow publishes every real version.
#
#   scripts/first-publish.sh            every public package not on npm yet
#   scripts/first-publish.sh <name>...  these packages, even while private
#
# Publishes only the placeholders, and only after you confirm each one.
# ──────────────────────────────────────────────────────────────────────────

REPO_OWNER="thomasfosterau"
REPO_NAME="effect-auth"
WORKFLOW="release.yml"
ENVIRONMENT="release"
REGISTRY="https://registry.npmjs.org"

cd "$(git rev-parse --show-toplevel)"

# on_npm NAME: whether the registry knows NAME at all.
on_npm() {
  local code
  code=$(curl -s -o /dev/null -w '%{http_code}' "$REGISTRY/${1/\//%2f}")
  [[ "$code" == "200" ]]
}

# Each workspace package as "name<TAB>directory<TAB>private".
PACKAGES=$(node -e '
  const { readdirSync, readFileSync, existsSync } = require("node:fs");
  for (const dir of readdirSync("packages")) {
    const path = `packages/${dir}/package.json`;
    if (!existsSync(path)) continue;
    const m = JSON.parse(readFileSync(path, "utf8"));
    console.log([m.name, `packages/${dir}`, m.private === true].join("\t"));
  }')

TARGETS=()
DIRS=()
printf '%sChecking npm for each workspace package…%s\n' "$DIM" "$RESET"
while IFS=$'\t' read -r name dir private; do
  if (( $# )); then
    [[ " $* " == *" $name "* ]] || continue
  else
    [[ "$private" == "false" ]] || continue
  fi
  if on_npm "$name"; then
    (( $# )) && printf '  %s is already on npm; skipping\n' "$name"
    continue
  fi
  TARGETS+=("$name")
  DIRS+=("$dir")
done <<< "$PACKAGES"

for wanted in "$@"; do
  grep -q "^${wanted}"$'\t' <<< "$PACKAGES" || { printf '%sNo workspace package named %s%s\n' "$RED" "$wanted" "$RESET"; exit 1; }
done

if (( ${#TARGETS[@]} == 0 )); then
  printf '%s✓ Nothing needs a first publish: every package checked is already on npm.%s\n' "$GREEN" "$RESET"
  (( $# )) || note "To prepare a package that is still private, name it: scripts/first-publish.sh @thomasfosterau/<name>"
  exit 0
fi

TOTAL_STAGES=$(( 2 + 2 * ${#TARGETS[@]} ))

banner "First publish: ${TARGETS[*]}"

# ── Preflight ─────────────────────────────────────────────────────────────
stage "Preflight: release environment and npm sign-in"
say "The publish job runs in the '$ENVIRONMENT' environment, and you publish the placeholders as yourself."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if gh api "repos/$REPO_OWNER/$REPO_NAME/environments/$ENVIRONMENT" >/dev/null 2>&1; then
    printf '  %s✓%s environment %s exists\n' "$GREEN" "$RESET" "$ENVIRONMENT"
  else
    warn "no '$ENVIRONMENT' environment on $REPO_OWNER/$REPO_NAME"
    open_url "https://github.com/$REPO_OWNER/$REPO_NAME/settings/environments/new"
    step "Name it '$ENVIRONMENT', add yourself as a required reviewer, and limit deployment branches to 'trunk'."
    pause "Press Enter once it exists"
  fi
else
  note "gh isn't signed in, so check by hand that the '$ENVIRONMENT' environment exists:"
  note "https://github.com/$REPO_OWNER/$REPO_NAME/settings/environments"
fi
if NPM_USER=$(npm whoami --registry "$REGISTRY" 2>/dev/null); then
  printf '  %s✓%s signed in to npm as %s\n' "$GREEN" "$RESET" "$NPM_USER"
else
  step "Sign in to npm as the account that owns the @$REPO_OWNER scope."
  npm login --registry "$REGISTRY"
  NPM_USER=$(npm whoami --registry "$REGISTRY")
  printf '  %s✓%s signed in to npm as %s\n' "$GREEN" "$RESET" "$NPM_USER"
fi
pause

# ── Per package ───────────────────────────────────────────────────────────
for i in "${!TARGETS[@]}"; do
  name="${TARGETS[$i]}"
  dir="${DIRS[$i]}"

  stage "$name: publish the placeholder"
  say "npm needs $name to exist before it can trust $WORKFLOW, so this publishes"
  say "an empty $name@0.0.0 (a package.json and a README, no code)."
  note "The Release workflow publishes the real version later, with provenance."
  if on_npm "$name"; then
    printf '  %s✓%s %s is on npm already; nothing to publish\n' "$GREEN" "$RESET" "$name"
    pause
  else
    scratch=$(mktemp -d)
    node -e '
      const [name, dir, owner, repo] = process.argv.slice(1);
      const manifest = {
        name,
        version: "0.0.0",
        description: "Placeholder so npm trusted publishing can be configured; the first real release replaces it.",
        license: "MIT",
        repository: { type: "git", url: `https://github.com/${owner}/${repo}.git`, directory: dir },
        publishConfig: { access: "public" },
      };
      require("node:fs").writeFileSync(process.argv[5], JSON.stringify(manifest, null, 2) + "\n");
    ' "$name" "$dir" "$REPO_OWNER" "$REPO_NAME" "$scratch/package.json"
    printf '# %s\n\nPlaceholder. See https://github.com/%s/%s/tree/trunk/%s\n' \
      "$name" "$REPO_OWNER" "$REPO_NAME" "$dir" > "$scratch/README.md"
    if confirm "Publish $name@0.0.0 to npm as $NPM_USER? (npm may ask for your 2FA code)"; then
      (cd "$scratch" && npm publish --access public --registry "$REGISTRY")
      printf '  %s✓ published%s %s@0.0.0\n' "$GREEN" "$RESET" "$name"
    else
      SKIPPED+=("$name: publish the placeholder, then add its trusted publisher")
      warn "skipped; re-run this wizard to publish it later"
      rm -rf "$scratch"
      pause
      continue
    fi
    rm -rf "$scratch"
    pause
  fi

  stage "$name: trust the Release workflow"
  open_url "https://www.npmjs.com/package/$name/access"
  step "Under 'Trusted Publisher', choose GitHub Actions and enter:"
  note "    Organization or user:  $REPO_OWNER"
  note "    Repository:            $REPO_NAME"
  note "    Workflow filename:     $WORKFLOW"
  note "    Environment name:      $ENVIRONMENT"
  step "Save the connection."
  step "Under 'Publishing access', choose 'Require two-factor authentication and disallow tokens', then save."
  note "If the page looks different, docs/PUBLISHING.md lists the same values."
  if ! confirm "Is the trusted publisher saved for $name?"; then
    SKIPPED+=("$name: add the trusted publisher at https://www.npmjs.com/package/$name/access")
  fi
done

# ── Wrap up ───────────────────────────────────────────────────────────────
stage "Before and after the first release"
say "Before the release: each package must be public in the repo, with a changeset"
say "that takes it above 0.0.0, so the Release workflow packs it."
for i in "${!TARGETS[@]}"; do
  name="${TARGETS[$i]}"
  if [[ $(node -p "require('./${DIRS[$i]}/package.json').private === true") == "true" ]]; then
    warn "$name is still private in ${DIRS[$i]}/package.json"
    SKIPPED+=("$name: make it public (drop \"private\", add publishConfig.access public), see CONTRIBUTING.md → Adding a package")
  fi
done
say "After the release publishes them, deprecate the placeholders:"
for name in "${TARGETS[@]}"; do
  note "    npm deprecate $name@0.0.0 \"Placeholder; use a later version.\""
done
note "Check the release used trusted publishing: the version's page on npm shows 'Built and signed on GitHub Actions'."
pause "Press Enter to finish"

finish
